Puppeteer en een ingebouwde Chromium-build staan nu in een tijdelijke map buiten het project. Die bevat de benodigde libraries zelf. Nu draai ik de homepage-test.
{"kind":"tool","id":"U4vlzUxOmVU","toolName":"run_terminal_command","input":{"command":"mkdir -p /workspace/chats/0cd6c92a83e7f88ff47ed426/artifacts && cat > /tmp/pwtest/test.mjs <<'EOF'
import chromium from "@sparticuz/chromium";
import puppeteer from "puppeteer-core";

const HOST = "pv-0cd6c92a83e7-bae2bc46-89c1-42ad-8741-eb7937600689.style.dev";
const OUT = "/workspace/chats/0cd6c92a83e7f88ff47ed426/artifacts";
const browser = await puppeteer.launch({
  executablePath: await chromium.executablePath(),
  args: [...chromium.args, `--host-resolver-rules=MAP ${HOST} 127.0.0.1:3000`, "--use-gl=swiftshader", "--enable-unsafe-swiftshader"],
  headless: true,
  defaultViewport: { width: 1280, height: 800 },
});
const page = await browser.newPage();
const errors = [];
page.on("console", (m) => { if (m.type() === "error" || m.type() === "warning") errors.push(`[${m.type()}] ${m.text()}`); });
page.on("pageerror", (e) => errors.push(`[pageerror] ${e.message}`));
page.on("requestfailed", (r) => errors.push(`[reqfail] ${r.url()} ${r.failure()?.errorText}`));

await page.goto(`http://${HOST}/`, { waitUntil: "networkidle0", timeout: 60000 });
await new Promise((r) => setTimeout(r, 1500));
await page.screenshot({ path: `${OUT}/home-top.png` });
const title = await page.title();
console.log("TITLE:", title);

await page.evaluate(() => window.scrollTo(0, 1100));
await new Promise((r) => setTimeout(r, 1800));
await page.screenshot({ path: `${OUT}/home-cards.png` });
const state = await page.evaluate(() => ({
  cards: document.querySelectorAll(".card").length,
  cardsIn: document.querySelectorAll(".card.is-in").length,
  planets: document.querySelectorAll(".planet").length,
  planetScale: getComputedStyle(document.querySelector(".card.is-in .planet") || document.querySelector(".planet")).scale,
  glowOn: document.querySelector(".cursor-glow")?.classList.contains("is-on") ?? null,
  glowDisplay: getComputedStyle(document.querySelector(".cursor-glow")).display,
}));
console.log("STATE:", JSON.stringify(state));

await page.mouse.move(600, 400);
await page.mouse.move(640, 420, { steps: 8 });
await new Promise((r) => setTimeout(r, 600));
console.log("GLOW_ON_AFTER_MOVE:", await page.evaluate(() => document.querySelector(".cursor-glow").classList.contains("is-on")));

const card = await page.$(".card");
await card.hover();
await new Promise((r) => setTimeout(r, 300));
await page.screenshot({ path: `${OUT}/home-hover.png` });

console.log("ERRORS:", errors.length ? errors.join("\n") : "none");
await browser.close();
EOF
