  const rim2 = measureRim();
  const dir = Math.sign(rim2 - rim1) || 1;
  const driftPerSec = Math.abs(rim2 - rim1) / (16 * 0.016);

  const bx = 0.16 * w, by = 0.82 * h;
  const P = 380;
  const strength = Math.min(1, P / (h * 0.5));
  const spd = h * 1.55 * (0.6 + strength * 0.95);
